CHANGELOG = '## [0.287.0] - a bank vault\'s money racks stand in rows\n\nThe walker, of the vault: "that vault room needs some love", with a photograph of a gold vault -- racks of blue\npainted steel in rows down the room, an aisle between. On 0.286.x a bank vault\'s money stood against its walls; its\n330 m2 rooms read empty in the middle.\n\n### Added\n- **`shelf_cash_row`**: Zoo 1.143.0\'s open-backed vault rack (`shelving`, stock `vault`), 2.4 or 1.8 x 0.6 x 1.4 m,\n  an ISLAND, capped at 8 a room and facing an aisle. 1.4 m is the corner store gondola\'s height and for its reason:\n  cover a body crouches behind and an eye at 1.60 m sees over, so the rows are lanes and not a maze. The wall racks\n  stay 1.9 m.\n- **A bank vault lays rows of them** (`bank_vault`\'s `rows`, `rows_share` 0.25), as a supermarket lays its gondolas:\n  whole rows, from the middle out, an aisle from every piece already standing.\n  - NO ROUTE RESERVATION. Reserving the routes as a shop floor does was measured first and cost\n    bank_tower_a03\'s teller cage both its cash carts and its locker for no row; without it the cage keeps them and\n    stands a row. The rows\' own aisle rule and the nav gate are what keep a route open.\n\n### Measured, the seven banks refurnished (`migrations/migrate_bank_money.py`)\n- Only the seven banks\' built slots moved; every other building\'s are 0.286.2\'s byte for byte.\n- 73 row racks: bank_branch_a02 16, a03 19, a04 10, bank_job 14, bank_tower_a01 to a03 6, 7 and 1, every one\n  `metal_bare` with shelving\'s `vault` stock. A 330 m2 vault stands up to 11, its share of floor under furniture\n  0.02-0.06 -> 0.04-0.08: the rows stop at the piece\'s cap, not at `rows_share`.\n- The nav gate\'s 157 shells pass: no row cuts a route. bank_branch_a02\'s count tables give way to the rows (3 -> 0\n  in its vaults), the rows taking the floor before the floor pieces.\n\n### Tests\n- `tests/test_bank_money.py`: the row piece, under shelter height, the vault\'s stock; rows in every library bank\'s\n  vaults (fails on 0.286.2).\n- `tests/test_furnish.py`: `bank_vault` joins the recipes that hand out islands and that give rows.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.286.2', 'Deli Counter 0.287.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
